// Assuming f_rand is defined elsewhere in the codebase
extern void f_rand(unsigned char*, size_t);

std::string generate_iv(int size, int source = 0) {
    if (size <= 0) {
        std::string error("Invalid IV size");
        std::cerr << "Warning: " << error << std::endl;
        return "false";
    }

    unsigned char* iv = new unsigned char[size];
    if (!iv) {
        std::cerr << "Warning: Memory allocation failed" << std::endl;
        return "false";
    }

    std::ifstream devrandom;
    const char* dev_name;
    if (source == 0) {
        dev_name = "/dev/random";
    } else if (source == 1) {
        dev_name = "/dev/urandom";
    } else {
        // Invalid source, use f_rand
        f_rand(iv, size);
    }

    if (source == 0 || source == 1) {
        devrandom.open(dev_name, std::ios::in | std::ios::binary);
        if (!devrandom.is_open()) {
            std::cerr << "Warning: Could not open device " << dev_name << std::endl;
            delete[] iv;
            return "false";
        }

        devrandom.read(reinterpret_cast<char*>(iv), size);
        if (!devrandom) {
            std::cerr << "Warning: Failed to read " << size << " bytes from " << dev_name << std::endl;
            devrandom.close();
            delete[] iv;
            return "false";
        }

        devrandom.close();
    }

    std::string result(reinterpret_cast<char*>(iv), size);
    delete[] iv;
    return result;
}

