extern "C" {
    void f_rand(void* buffer, size_t size);
}

bool generate_iv(int size, int source = 0) {
    if (size <= 0) {
        std::cerr << "Warning: Invalid size for IV." << std::endl;
        return false;
    }

    std::string iv;
    try {
        iv.resize(size);
    } catch (...) {
        std::cerr << "Warning: Memory allocation for IV failed." << std::endl;
        return false;
    }

    if (source == 0) {
        std::ifstream random("/dev/random", std::ios::in | std::ios::binary);
        if (!random) {
            std::cerr << "Warning: Could not open /dev/random." << std::endl;
            return false;
        }

        if (!random.read(&iv[0], size)) {
            std::cerr << "Warning: Failed to read from /dev/random." << std::endl;
            return false;
        }
    } else if (source == 1) {
        std::ifstream urandom("/dev/urandom", std::ios::in | std::ios::binary);
        if (!urandom) {
            std::cerr << "Warning: Could not open /dev/urandom." << std::endl;
            return false;
        }

        if (!urandom.read(&iv[0], size)) {
            std::cerr << "Warning: Failed to read from /dev/urandom." << std::endl;
            return false;
        }
    } else {
        f_rand(&iv[0], size);
    }

    return !iv.empty();
}

