#define RANDOM 0
#define URANDOM 1

std::string generate_iv(int size, int source = 0) {
    if (size <= 0) {
        std::cerr << "Warning: Invalid IV size requested." << std::endl;
        return "false";
    }

    char* iv = new (std::nothrow) char[size];
    if (!iv) {
        std::cerr << "Warning: Failed to allocate memory for IV." << std::endl;
        return "false";
    }

    if (source == RANDOM || source == URANDOM) {
        const char* device = (source == RANDOM) ? "/dev/random" : "/dev/urandom";
        int fd = open(device, O_RDONLY);
        if (fd == -1) {
            std::cerr << "Warning: Could not open random device: " << device << std::endl;
            delete[] iv;
            return "false";
        }

        ssize_t bytes_read = read(fd, iv, size);
        close(fd);
        if (bytes_read != static_cast<ssize_t>(size)) {
            std::cerr << "Warning: Failed to read sufficient random bytes." << std::endl;
            delete[] iv;
            return "false";
        }
    } else {
        for (int i = 0; i < size; ++i) {
            iv[i] = f_rand();
            if (iv[i] == EOF) {
                std::cerr << "Warning: Random byte generation failed." << std::endl;
                delete[] iv;
                return "false";
            }
        }
    }

    std::string result(iv, size);
    delete[] iv;
    return result;
}

